+.message-bubble__subagent-thinking {
+  padding: 6px 10px;
+  margin: 4px 0;
+  border-left: 3px solid var(--color-border, #e0e0e0);
+  font-size: 0.85em;
+  color: var(--color-text-secondary, #666);
+  white-space: pre-wrap;
+}
+
+.message-bubble__subagent-sql-group {
+  margin: 4px 0 4px 10px;
+  cursor: default;
+}
+
