+  display: flex;
+  align-items: center;
+  gap: 6px;
+  cursor: pointer;
+  font-size: 0.8em;
+  color: var(--color-text-disabled, #999);
+  user-select: none;
+  padding: 2px 0;
+  list-style: none;
+}
+
+.message-bubble__subagent-sql-summary::-webkit-details-marker {
+  display: none;
+}
+
+.message-bubble__subagent-sql-summary::before {
+  content: '▶';
+  font-size: 8px;
+  color: var(--color-text-disabled);
+  transition: transform 0.15s ease;
+  flex-shrink: 0;
+}
+
+.message-bubble__subagent-sql-group[open] > .message-bubble__subagent-sql-summary::before {
+  transform: rotate(90deg);
+}
+
+.message-bubble__subagent-sql-body {
+  padding-top: 4px;
+}
+
 .message-bubble__chart-in-answer {
   margin: 20px 0;
 }
