  1→import { useState, useRef, useEffect } from 'react';
  2→import ReactMarkdown from 'react-markdown';
  3→import remarkGfm from 'remark-gfm';
  4→import { useTranslation } from '../hooks/useTranslation';
  5→import type { ChatMessage, ContentSegment } from '../types';
  6→import { useAgent } from '../hooks/useAgent';
  7→import { InlineQueryResult } from './InlineQueryResult';
  8→import { ChartWidget } from './ChartWidget';
  9→import { VegaLiteChartWidget } from './VegaLiteChartWidget';
 10→import { UserQuestion } from './UserQuestion';
 11→import './MessageBubble.css';
 12→
 13→/**
 14→ * Strip chart_spec JSON code blocks from answer text.
 15→ * The orchestrator may include the raw chart spec JSON even though the chart
 16→ * is rendered separately. Remove ```json ... ``` blocks containing chart_spec
 17→ * or Plotly trace data so they don't appear as raw text.
 18→ */
 19→function stripChartSpecBlocks(text: string): string {
 20→  return text.replace(/```(?:json)?\s*\n?\s*\{[\s\S]*?"(?:chart_spec|data)"[\s\S]*?\}\s*\n?\s*```/g, '').trim();
 21→}
 22→
 23→/**
 24→ * Fix missing line breaks before bold section headers in text.
 25→ * The model sometimes concatenates bold headers directly after the previous
 26→ * sentence (e.g. "...for arrays.**Preparing data arrays**"). This inserts
 27→ * paragraph breaks so they render on new lines.
 28→ */
 29→function fixBoldHeaderLineBreaks(text: string): string {
 30→  // Insert \n\n before **Header** when preceded by sentence-ending punctuation
 31→  // with no whitespace. The [A-Z] ensures we only match section-header-style
 32→  // bold (starting with a capital letter), avoiding inline bold like **data**.
 33→  return text.replace(/([.!?:])(\*\*[A-Z])/g, '$1\n\n$2');
 34→}
 35→
 36→/** Strip markdown formatting for plain-text preview display. */
 37→function stripMarkdown(text: string): string {
 38→  return text
 39→    .replace(/\*\*(.+?)\*\*/g, '$1')   // **bold**
 40→    .replace(/__(.+?)__/g, '$1')        // __bold__
 41→    .replace(/\*(.+?)\*/g, '$1')        // *italic*
 42→    .replace(/_(.+?)_/g, '$1')          // _italic_
 43→    .replace(/`(.+?)`/g, '$1')          // `code`
 44→    .replace(/^#+\s+/gm, '');           // # headings
 45→}
 46→
 47→function getLastThinkingLine(segments: ContentSegment[], streamingRemainder: string | undefined, t: (key: string) => string): string {
 48→  // Use streaming remainder if available
 49→  if (streamingRemainder?.trim()) {
 50→    const lines = streamingRemainder.trim().split('\n').filter((l) => l.trim());
 51→    const last = stripMarkdown(lines[lines.length - 1] || '');
 52→    return last.length > 100 ? last.slice(0, 100) + '...' : last;
 53→  }
 54→  // Otherwise use last thinking segment's last line
 55→  for (let i = segments.length - 1; i >= 0; i--) {
 56→    if (segments[i].type === 'thinking' && segments[i].text?.trim()) {
 57→      const lines = segments[i].text!.trim().split('\n').filter((l) => l.trim());
 58→      const last = stripMarkdown(lines[lines.length - 1] || '');
 59→      return last.length > 100 ? last.slice(0, 100) + '...' : last;
 60→    }
 61→  }
 62→  return t('thinking');
 63→}
 64→
 65→function ThinkingBlock({ segments, streamingRemainder, isThinkingPhase, isAgentStreaming, hasAnswer }: {
 66→  segments: ContentSegment[];
 67→  streamingRemainder?: string;
 68→  isThinkingPhase: boolean;
 69→  isAgentStreaming: boolean;
 70→  hasAnswer: boolean;
 71→}) {
 72→  const { t } = useTranslation();
 73→  // All non-answer, non-chart, non-user_question segments go inside the thinking block.
 74→  // subagent_end with sqlResults always stays in thinking; text-only subagent_end without
 75→  // answer goes to the answer block as a preliminary result.
 76→  const thinkingSegments = segments.filter(
 77→    (s) => s.type !== 'answer' && s.type !== 'user_question' && !(s.type === 'tool' && s.toolResult?.chart_spec) && !(s.type === 'subagent_end' && (s.chart_spec || (!s.sqlResults?.length && s.text?.trim() && !hasAnswer)))
 78→  );
 79→  const hasContent = thinkingSegments.some(
 80→    (s) => (s.type === 'thinking' && s.text?.trim()) || (s.type === 'tool' && s.toolResult) || s.type === 'subagent_start' || (s.type === 'subagent_end' && !s.chart_spec && (s.text?.trim() || s.sqlResults?.length))
 81→  ) || streamingRemainder?.trim();
 82→
 83→  if (!hasContent) return null;
 84→
 85→  // Show preview only while agent is still working (hidden by CSS when collapsible is open anyway)
 86→  const summary = isAgentStreaming ? getLastThinkingLine(segments, streamingRemainder, t) : '';
 87→
 88→  return (
 89→    <details className="message-bubble__segment message-bubble__segment--thinking message-bubble__collapsible" open={isThinkingPhase || (!hasAnswer && !isAgentStreaming) || undefined}>
 90→      <summary className="message-bubble__collapsible-summary">
 91→        <span className="message-bubble__segment-label">{t('thinkingLabel')}</span>
 92→        {summary && <span className="message-bubble__collapsible-preview">{summary}</span>}
 93→      </summary>
 94→      <div className="message-bubble__thinking-body">
 95→        {thinkingSegments.map((seg, i) => {
 96→          if (seg.type === 'thinking' && seg.text?.trim()) {
 97→            return (
 98→              <div key={i} className="message-bubble__segment-content">
 99→                <ReactMarkdown remarkPlugins={[remarkGfm]}>{fixBoldHeaderLineBreaks(seg.text)}</ReactMarkdown>
100→              </div>
101→            );
102→          }
103→          if (seg.type === 'tool' && seg.toolResult) {
104→            return (
105→              <div key={i} className="message-bubble__tool-segment">
106→                <InlineQueryResult result={seg.toolResult} />
107→              </div>
108→            );
109→          }
110→          if (seg.type === 'subagent_start') {
111→            const displayName = seg.subagentName === 'sql-analyst'
112→              ? t('sqlAnalystWorking')
113→              : `${seg.subagentName} working...`;
114→            return (
115→              <div key={i} className="message-bubble__subagent-indicator">
116→                <span className="message-bubble__subagent-label">{displayName}</span>
117→              </div>
118→            );
119→          }
120→          if (seg.type === 'subagent_end' && !seg.chart_spec && (seg.sqlResults?.length || seg.text?.trim())) {
121→            // Render SQL results using InlineQueryResult — same as direct tool calls
122→            if (seg.sqlResults?.length) {
123→              return (
124→                <div key={i}>
125→                  {seg.sqlResults.map((sqlResult, qi) => (
126→                    <div key={qi} className="message-bubble__tool-segment">
127→                      <InlineQueryResult result={{
128→                        toolCallId: `${seg.subagentId}-sql-${qi}`,
129→                        toolName: 'execute_sql',
130→                        sql: sqlResult.sql,
131→                        columns: sqlResult.columns ?? [],
132→                        rows: sqlResult.rows ?? [],
133→                        rowCount: sqlResult.rowCount ?? 0,
134→                        error: sqlResult.error,
135→                      }} />
136→                    </div>
137→                  ))}
138→                </div>
139→              );
140→            }
141→            return (
142→              <div key={i} className="message-bubble__segment-content">
143→                <ReactMarkdown remarkPlugins={[remarkGfm]}>{seg.text!}</ReactMarkdown>
144→              </div>
145→            );
146→          }
147→          return null;
148→        })}
149→        {streamingRemainder?.trim() && (
150→          <div className="message-bubble__segment-content">
151→            <ReactMarkdown remarkPlugins={[remarkGfm]}>{fixBoldHeaderLineBreaks(streamingRemainder)}</ReactMarkdown>
152→          </div>
153→        )}
154→      </div>
155→    </details>
156→  );
157→}
158→
159→function ErrorBlock({ errorMessage, onRetry }: { errorMessage: string; onRetry?: () => void }) {
160→  const { t } = useTranslation();
161→  return (
162→    <div className="message-bubble__segment message-bubble__segment--error">
163→      <div className="message-bubble__error-header">{t('errorOccurred')}</div>
164→      <div className="message-bubble__error-message">{errorMessage}</div>
165→      {onRetry && (
166→        <button className="message-bubble__error-retry" onClick={onRetry}>
167→          {t('tryAgain')}
168→        </button>
169→      )}
170→    </div>
171→  );
172→}
173→
174→function formatDuration(ms: number): string {
175→  if (ms < 1000) return '<1s';
176→  const seconds = Math.round(ms / 1000);
177→  if (seconds < 60) return `${seconds}s`;
178→  const minutes = Math.floor(seconds / 60);
179→  const remainingSeconds = seconds % 60;
180→  return remainingSeconds > 0 ? `${minutes}m ${remainingSeconds}s` : `${minutes}m`;
181→}
182→
183→export function MessageBubble({ message, messageIndex }: { message: ChatMessage; messageIndex: number }) {
184→  const { t } = useTranslation();
185→  const { isStreaming, editMessage, deleteMessage, sendMessage, messages } = useAgent();
186→  const [isEditing, setIsEditing] = useState(false);
187→  const [editText, setEditText] = useState(message.content);
188→  const [isConfirmingDelete, setIsConfirmingDelete] = useState(false);
189→  const textareaRef = useRef<HTMLTextAreaElement>(null);
190→
191→  const isUser = message.role === 'user';
192→  const hasSegments = !isUser && message.segments && message.segments.length > 0;
193→
194→  useEffect(() => {
195→    if (isEditing && textareaRef.current) {
196→      textareaRef.current.focus();
197→      textareaRef.current.selectionStart = textareaRef.current.value.length;
198→    }
199→  }, [isEditing]);
200→
201→  const handleEdit = () => {
202→    setEditText(message.content);
203→    setIsEditing(true);
204→    setIsConfirmingDelete(false);
205→  };
206→
207→  const handleCancelEdit = () => {
208→    setIsEditing(false);
209→    setEditText(message.content);
210→  };
211→
212→  const handleSaveEdit = () => {
213→    const trimmed = editText.trim();
214→    if (!trimmed || trimmed === message.content) {
215→      handleCancelEdit();
216→      return;
217→    }
218→    setIsEditing(false);
219→    editMessage(messageIndex, trimmed);
220→  };
221→
222→  const handleDeleteConfirm = () => {
223→    setIsConfirmingDelete(false);
224→    deleteMessage(messageIndex);
225→  };
226→
227→  const handleKeyDown = (e: React.KeyboardEvent) => {
228→    if (e.key === 'Escape') {
229→      handleCancelEdit();
230→    } else if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) {
231→      e.preventDefault();
232→      handleSaveEdit();
233→    }
234→  };
235→
236→  let streamingRemainder: string | undefined;
237→  if (hasSegments && message.isStreaming && message.content) {
238→    const segmentedText = message.segments!
239→      .filter((s) => s.type === 'thinking' || s.type === 'answer')
240→      .map((s) => s.text || '')
241→      .join('');
242→    const remaining = message.content.slice(segmentedText.length);
243→    if (remaining.trim()) {
244→      streamingRemainder = remaining;
245→    }
246→  }
247→
248→  const hasAnswer = !!hasSegments && message.segments!.some((s) => s.type === 'answer');
249→  const isInAnswerPhase = message.currentPhase === 'answer';
250→  const isThinkingPhase = !!message.isStreaming && !hasAnswer && !isInAnswerPhase;
251→
252→  const hasCharts = hasSegments && message.segments!.some(
253→    (s) => (s.type === 'tool' && s.toolResult?.chart_spec) || (s.type === 'subagent_end' && s.chart_spec)
254→  );
255→
256→  const answerBlockSegments = hasSegments
257→    ? message.segments!
258→        .filter((s) =>
259→          (s.type === 'answer' && s.text?.trim()) ||
260→          (s.type === 'subagent_end' && !s.chart_spec && !s.sqlResults?.length && s.text?.trim() && !hasAnswer) ||
261→          (s.type === 'tool' && s.toolResult?.chart_spec) ||
262→          (s.type === 'subagent_end' && s.chart_spec)
263→        )
264→        .map((s) => {
265→          if ((s.type === 'answer' || (s.type === 'subagent_end' && !s.chart_spec)) && s.text && hasCharts) {
266→            return { ...s, text: stripChartSpecBlocks(s.text) };
267→          }
268→          return s;
269→        })
270→        .filter((s) => {
271→          // Remove text segments that became empty after stripping chart blocks
272→          if ((s.type === 'answer' || (s.type === 'subagent_end' && !s.chart_spec)) && !s.text?.trim()) {
273→            return false;
274→          }
275→          return true;
276→        })
277→    : [];
278→
279→  const questionSegments = hasSegments
280→    ? message.segments!.filter((s) => s.type === 'user_question' && s.questionData)
281→    : [];
282→
283→  return (
284→    <div className={`message-bubble message-bubble--${message.role}`}>
285→      <div className="message-bubble__header">
286→        {isUser ? t('you') : t('assistant')}
287→        {isUser && !isStreaming && !isEditing && !isConfirmingDelete && (
288→          <span className="message-bubble__actions">
289→            <button
290→              className="message-bubble__action-btn"
291→              onClick={handleEdit}
292→              title={t('editMessage')}
293→            >
294→              &#9998;
295→            </button>
296→            <button
297→              className="message-bubble__action-btn message-bubble__action-btn--delete"
298→              onClick={() => setIsConfirmingDelete(true)}
299→              title={t('deleteMessage')}
300→            >
301→              &#128465;
302→            </button>
303→          </span>
304→        )}
305→      </div>
306→
307→      {isUser && isConfirmingDelete && (
308→        <div className="message-bubble__confirm-delete">
309→          <span>{t('deleteConfirm')}</span>
310→          <div className="message-bubble__confirm-actions">
311→            <button
312→              className="message-bubble__confirm-btn message-bubble__confirm-btn--delete"
313→              onClick={handleDeleteConfirm}
314→            >
315→              {t('delete')}
316→            </button>
317→            <button
318→              className="message-bubble__confirm-btn"
319→              onClick={() => setIsConfirmingDelete(false)}
320→            >
321→              {t('cancel')}
322→            </button>
323→          </div>
324→        </div>
325→      )}
326→
327→      {isUser && isEditing ? (
328→        <div className="message-bubble__edit-mode">
329→          <textarea
330→            ref={textareaRef}
331→            className="message-bubble__edit-textarea"
332→            value={editText}
333→            onChange={(e) => setEditText(e.target.value)}
334→            onKeyDown={handleKeyDown}
335→            rows={3}
336→          />
337→          <div className="message-bubble__edit-actions">
338→            <button
339→              className="message-bubble__edit-btn message-bubble__edit-btn--save"
340→              onClick={handleSaveEdit}
341→            >
342→              {t('saveResend')}
343→            </button>
344→            <button
345→              className="message-bubble__edit-btn"
346→              onClick={handleCancelEdit}
347→            >
348→              {t('cancel')}
349→            </button>
350→          </div>
351→        </div>
352→      ) : hasSegments ? (
353→        <div className="message-bubble__segments">
354→          {!questionSegments.some((s) => !s.userAnswer) && (
355→            <ThinkingBlock
356→              segments={message.segments!}
357→              streamingRemainder={isThinkingPhase ? streamingRemainder : undefined}
358→              isThinkingPhase={isThinkingPhase}
359→              isAgentStreaming={!!message.isStreaming}
360→              hasAnswer={hasAnswer}
361→            />
362→          )}
363→          {questionSegments.map((seg, i) => (
364→            <div key={`question-${i}`} className="message-bubble__segment message-bubble__segment--question">
365→              <UserQuestion
366→                questionData={seg.questionData!}
367→                userAnswer={seg.userAnswer}
368→                userFreeText={seg.userFreeText}
369→                answerDurationMs={seg.answerDurationMs}
370→              />
371→            </div>
372→          ))}
373→          {answerBlockSegments.length > 0 && (
374→            <div className="message-bubble__segment message-bubble__segment--answer">
375→              <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
376→              {answerBlockSegments.map((seg, i) => {
377→                // Chart segment (tool with chart_spec or subagent_end with chart_spec)
378→                if ((seg.type === 'tool' && seg.toolResult?.chart_spec) || (seg.type === 'subagent_end' && seg.chart_spec)) {
379→                  return (
380→                    <div key={`chart-${i}`} className="message-bubble__chart-in-answer">
381→                      {seg.type === 'tool' && seg.toolResult ? (
382→                        <InlineQueryResult result={seg.toolResult!} />
383→                      ) : seg.chart_spec ? (
384→                        seg.chart_spec.library === 'vegalite' && seg.chart_spec.spec
385→                          ? <VegaLiteChartWidget spec={seg.chart_spec.spec} />
386→                          : <ChartWidget data={seg.chart_spec.data ?? []} layout={seg.chart_spec.layout} frames={seg.chart_spec.frames} />
387→                      ) : null}
388→                    </div>
389→                  );
390→                }
391→                // Text segment (answer or subagent_end without chart_spec)
392→                return (
393→                  <div key={`answer-${i}`} className="message-bubble__segment-content">
394→                    <ReactMarkdown remarkPlugins={[remarkGfm]}>{fixBoldHeaderLineBreaks(seg.text!)}</ReactMarkdown>
395→                  </div>
396→                );
397→              })}
398→              {/* Render streaming remainder inside the same answer block to avoid duplicate headers */}
399→              {isInAnswerPhase && streamingRemainder?.trim() && (() => {
400→                const displayText = hasCharts ? stripChartSpecBlocks(streamingRemainder) : streamingRemainder;
401→                return displayText?.trim() ? (
402→                  <div className="message-bubble__segment-content">
403→                    <ReactMarkdown remarkPlugins={[remarkGfm]}>{fixBoldHeaderLineBreaks(displayText)}</ReactMarkdown>
404→                  </div>
405→                ) : null;
406→              })()}
407→              {!message.isStreaming && message.durationMs != null && (
408→                <div className="message-bubble__duration">
409→                  {t('answeredIn', { time: formatDuration(message.durationMs) })}
410→                </div>
411→              )}
412→            </div>
413→          )}
414→          {/* Only show standalone streaming answer block when no answer segments exist yet */}
415→          {answerBlockSegments.length === 0 && isInAnswerPhase && streamingRemainder?.trim() && (() => {
416→            const displayText = hasCharts ? stripChartSpecBlocks(streamingRemainder) : streamingRemainder;
417→            return displayText?.trim() ? (
418→              <div className="message-bubble__segment message-bubble__segment--answer">
419→                <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
420→                <div className="message-bubble__segment-content">
421→                  <ReactMarkdown remarkPlugins={[remarkGfm]}>{fixBoldHeaderLineBreaks(displayText)}</ReactMarkdown>
422→                </div>
423→              </div>
424→            ) : null;
425→          })()}
426→          {message.segments!.filter((s) => s.type === 'error').map((seg, i) => {
427→            const lastUserMsg = messages.slice().reverse().find((m) => m.role === 'user');
428→            const handleRetry = lastUserMsg ? () => sendMessage(lastUserMsg.content) : undefined;
429→            return <ErrorBlock key={`error-${i}`} errorMessage={seg.errorMessage || 'Unknown error'} onRetry={!isStreaming ? handleRetry : undefined} />;
430→          })}
431→          {message.isStreaming && !message.content && questionSegments.length === 0 && (
432→            <span className="message-bubble__typing">{t('thinking')}</span>
433→          )}
434→        </div>
435→      ) : (
436→        <>
437→          <div className="message-bubble__content">
438→            {message.content ? (
439→              <ReactMarkdown remarkPlugins={[remarkGfm]}>{fixBoldHeaderLineBreaks(message.content)}</ReactMarkdown>
440→            ) : message.isStreaming ? (
441→              <span className="message-bubble__typing">{t('thinking')}</span>
442→            ) : null}
443→          </div>
444→          {message.toolCalls && message.toolCalls.length > 0 && (
445→            <div className="message-bubble__tools">
446→              {message.toolCalls.map((tc) => (
447→                <InlineQueryResult key={tc.toolCallId} result={tc} />
448→              ))}
449→            </div>
450→          )}
451→        </>
452→      )}
453→    </div>
454→  );
455→}
