  1→import {
  2→  useCallback,
  3→  useEffect,
  4→  useRef,
  5→  useState,
  6→  type ReactNode,
  7→} from 'react';
  8→import { AgentContext } from '../hooks/useAgent';
  9→import { runAgentLoop, runAgentEditLoop } from '../agent/agentService';
 10→import type { ChatMessage, ContentSegment, ToolCallResult } from '../types';
 11→import { useSessionId } from '../hooks/useSessionId';
 12→import { useChartLibrary } from '../hooks/useChartLibrary';
 13→import { generateUUID } from '../utils/uuid';
 14→
 15→interface StreamState {
 16→  assistantId: string;
 17→  segments: ContentSegment[];
 18→  currentText: string;
 19→  textBuffer: string;
 20→  phase: 'thinking' | 'answer';
 21→  abortController: AbortController;
 22→  sessionId: string | null;
 23→  messages: ChatMessage[];
 24→  flushTimer: ReturnType<typeof setTimeout> | null;
 25→  startTime: number;
 26→}
 27→
 28→function generateId() {
 29→  return generateUUID();
 30→}
 31→
 32→export function AgentProvider({
 33→  children,
 34→  refreshTables,
 35→}: {
 36→  children: ReactNode;
 37→  refreshTables: () => Promise<void>;
 38→}) {
 39→  const userSessionId = useSessionId();
 40→  const { chartLibrary } = useChartLibrary();
 41→  const [messages, setMessages] = useState<ChatMessage[]>([]);
 42→  const [isStreaming, setIsStreaming] = useState(false);
 43→  const sessionIdRef = useRef<string | null>(null);
 44→  const pendingHistoryRef = useRef<{ role: string; content: string }[] | null>(null);
 45→  // Keep a ref in sync with messages so sendMessage always reads the latest
 46→  const messagesRef = useRef<ChatMessage[]>(messages);
 47→  useEffect(() => { messagesRef.current = messages; }, [messages]);
 48→  // Cache messages per conversation so switching away doesn't lose in-progress data
 49→  const messagesCacheRef = useRef<Map<string, ChatMessage[]>>(new Map());
 50→  // Track which conversation is currently displayed so background streams can detect they're stale
 51→  const activeConversationIdRef = useRef<string | null>(null);
 52→
 53→  // Per-conversation stream state map (replaces all singleton streaming refs)
 54→  const streamStatesRef = useRef<Map<string, StreamState>>(new Map());
 55→  const [streamingConversationIds, setStreamingConversationIds] = useState<Set<string>>(new Set());
 56→
 57→  const flushTextForStream = useCallback((state: StreamState, conversationId: string | null) => {
 58→    const text = state.textBuffer;
 59→    if (!text) return;
 60→    state.currentText += text;
 61→    state.textBuffer = '';
 62→
 63→    // Update the stream's own messages
 64→    state.messages = state.messages.map((m) =>
 65→      m.id === state.assistantId ? { ...m, content: m.content + text } : m
 66→    );
 67→
 68→    // If this conversation is currently being viewed, update React state
 69→    if (activeConversationIdRef.current === conversationId) {
 70→      setMessages(state.messages);
 71→    }
 72→  }, []);
 73→
 74→  const sendMessage = useCallback(
 75→    async (text: string, conversationId?: string | null) => {
 76→      const convId = conversationId || null;
 77→      // Per-conversation guard: don't double-send in same conversation
 78→      if (convId && streamStatesRef.current.has(convId)) return;
 79→      // Fallback guard for null-convId path (new chat before conversation created)
 80→      if (!convId && isStreaming) return;
 81→
 82→      const controller = new AbortController();
 83→      const assistantId = generateId();
 84→
 85→      const userMsg: ChatMessage = {
 86→        id: generateId(),
 87→        role: 'user',
 88→        content: text,
 89→      };
 90→      const assistantMsg: ChatMessage = {
 91→        id: assistantId,
 92→        role: 'assistant',
 93→        content: '',
 94→        toolCalls: [],
 95→        isStreaming: true,
 96→      };
 97→
 98→      // Build conversation history from current messages or cached messages
 99→      const currentMsgs = convId && activeConversationIdRef.current === convId
100→        ? messagesRef.current
101→        : (convId ? messagesCacheRef.current.get(convId) : messagesRef.current) || messagesRef.current;
102→      const history = currentMsgs
103→        .filter((m) => m.role === 'user' || m.role === 'assistant')
104→        .map((m) => ({ role: m.role, content: m.content }));
105→
106→      const streamMessages = [...currentMsgs, userMsg, assistantMsg];
107→
108→      // Create per-conversation stream state
109→      const state: StreamState = {
110→        assistantId,
111→        segments: [],
112→        currentText: '',
113→        textBuffer: '',
114→        phase: 'thinking',
115→        abortController: controller,
116→        sessionId: sessionIdRef.current,
117→        messages: streamMessages,
118→        flushTimer: null,
119→        startTime: Date.now(),
120→      };
121→
122→      if (convId) {
123→        streamStatesRef.current.set(convId, state);
124→        setStreamingConversationIds(prev => new Set(prev).add(convId));
125→      }
126→
127→      // Sync the ref when sending to a newly-created conversation whose ID
128→      // hasn't propagated through loadMessages/clearMessages yet.
129→      if (convId && activeConversationIdRef.current !== convId) {
130→        activeConversationIdRef.current = convId;
131→      }
132→
133→      // If this is the active conversation, update React state
134→      if (activeConversationIdRef.current === convId) {
135→        setMessages(streamMessages);
136→        setIsStreaming(true);
137→      }
138→
139→      // If there's pending history from a delete, start a new Langfuse session
140→      const pendingHistory = pendingHistoryRef.current;
141→      pendingHistoryRef.current = null;
142→      const langfuseSessionId = pendingHistory ? generateUUID() : null;
143→
144→      // Extract skill references
145→      let actualMessage = text;
146→      let skills: string[] | undefined;
147→      const slashMatches = [...text.matchAll(/\/([a-z0-9-]+)/g)];
148→      if (slashMatches.length > 0) {
149→        skills = slashMatches.map((m) => m[1]);
150→        actualMessage = slashMatches.reduce((msg, m) => msg.replace(m[0], ''), text).trim() || text;
151→      }
152→
153→      // Helper to update stream messages and optionally React state
154→      const updateMessages = (updater: (msgs: ChatMessage[]) => ChatMessage[]) => {
155→        state.messages = updater(state.messages);
156→        if (activeConversationIdRef.current === convId) {
157→          setMessages(state.messages);
158→        }
159→      };
160→
161→      // Helper to schedule text flush
162→      const scheduleFlush = () => {
163→        if (!state.flushTimer) {
164→          state.flushTimer = setTimeout(() => {
165→            flushTextForStream(state, convId);
166→            state.flushTimer = null;
167→          }, 50);
168→        }
169→      };
170→
171→      // Helper to flush pending text immediately
172→      const flushNow = () => {
173→        if (state.flushTimer) {
174→          clearTimeout(state.flushTimer);
175→          state.flushTimer = null;
176→        }
177→        flushTextForStream(state, convId);
178→      };
179→
180→      // Helper to finalize stream (called by onDone and onError)
181→      const cleanupStream = () => {
182→        if (state.flushTimer) {
183→          clearTimeout(state.flushTimer);
184→          state.flushTimer = null;
185→        }
186→        if (convId) {
187→          streamStatesRef.current.delete(convId);
188→          setStreamingConversationIds(prev => {
189→            const next = new Set(prev);
190→            next.delete(convId);
191→            return next;
192→          });
193→        }
194→      };
195→
196→      await runAgentLoop(
197→        actualMessage,
198→        state.sessionId,
199→        langfuseSessionId,
200→        pendingHistory ?? (history.length > 0 ? history : null),
201→        conversationId,
202→        {
203→          onTextChunk: (chunk) => {
204→            state.textBuffer += chunk;
205→            scheduleFlush();
206→          },
207→          onThinkingDone: () => {
208→            flushNow();
209→            if (state.currentText.trim()) {
210→              state.segments.push({ type: 'thinking', text: state.currentText });
211→              state.currentText = '';
212→            }
213→            state.phase = 'answer';
214→            updateMessages(msgs =>
215→              msgs.map(m =>
216→                m.id === assistantId
217→                  ? { ...m, currentPhase: 'answer', segments: [...state.segments] }
218→                  : m
219→              )
220→            );
221→          },
222→          onToolCall: (pending: ToolCallResult) => {
223→            flushNow();
224→            if (state.currentText.trim()) {
225→              const segType = state.phase === 'answer' ? 'answer' : 'thinking';
226→              state.segments.push({ type: segType, text: state.currentText });
227→              state.currentText = '';
228→            }
229→            state.segments.push({ type: 'tool', toolResult: pending });
230→            updateMessages(msgs =>
231→              msgs.map(m =>
232→                m.id === assistantId
233→                  ? { ...m, currentPhase: 'answer', segments: [...state.segments] }
234→                  : m
235→              )
236→            );
237→          },
238→          onToolResult: (result: ToolCallResult) => {
239→            const pendingIdx = state.segments.findIndex(
240→              s => s.type === 'tool' && s.toolResult?.toolCallId === result.toolCallId
241→            );
242→            if (pendingIdx !== -1) {
243→              const pending = state.segments[pendingIdx].toolResult!;
244→              state.segments[pendingIdx] = {
245→                type: 'tool',
246→                toolResult: {
247→                  ...pending,
248→                  ...result,
249→                  sql: result.sql || pending.sql,
